-- Audit store for the worker: what it did and saw, not the business state the API owns.
-- Every table splits metadata (kept indefinitely) from content (cleared after the
-- retention window by purge_audit_content()). IDs are generated by the worker so the
-- local outbox can resend a record without duplicating it.

BEGIN;

CREATE TABLE schema_migrations (
    version     text        PRIMARY KEY,
    applied_at  timestamptz NOT NULL DEFAULT now()
);

-- One row per worker execution.
CREATE TABLE runs (
    id              uuid        PRIMARY KEY,
    machine         text        NOT NULL,
    environment     text        NOT NULL CHECK (environment IN ('local', 'production')),
    api_base_url    text        NOT NULL,
    worker_version  text        NOT NULL,
    started_at      timestamptz NOT NULL,
    last_seen_at    timestamptz NOT NULL,
    ended_at        timestamptz,
    -- NULL with ended_at NULL and a stale last_seen_at: the run died without saying so.
    end_reason      text        CHECK (end_reason IN ('stopped', 'crashed'))
);
CREATE INDEX runs_started_at_idx ON runs (started_at DESC);

-- One row each time a run works on a search; a released search reclaimed later is a new row.
CREATE TABLE search_attempts (
    id                   uuid        PRIMARY KEY,
    run_id               uuid        NOT NULL REFERENCES runs (id),
    api_search_id        text        NOT NULL,
    profession           text        NOT NULL,
    city                 text        NOT NULL,
    max_results          integer,
    started_at           timestamptz NOT NULL,
    ended_at             timestamptz,
    outcome              text        CHECK (outcome IN (
                             'completed', 'failed',
                             'released_interrupted', 'released_api_unreachable')),
    error                text,
    cards_seen           integer     NOT NULL DEFAULT 0,
    cards_skipped_known  integer     NOT NULL DEFAULT 0,
    leads_reported       integer     NOT NULL DEFAULT 0,
    leads_inserted       integer     NOT NULL DEFAULT 0
);
CREATE INDEX search_attempts_run_idx    ON search_attempts (run_id);
CREATE INDEX search_attempts_search_idx ON search_attempts (api_search_id);
CREATE INDEX search_attempts_started_idx ON search_attempts (started_at DESC);

-- Every Google Maps card the scrape looked at, kept or not.
CREATE TABLE cards (
    id                 uuid        PRIMARY KEY,
    search_attempt_id  uuid        NOT NULL REFERENCES search_attempts (id),
    seen_at            timestamptz NOT NULL,
    outcome            text        NOT NULL CHECK (outcome IN ('reported', 'skipped_known_domain')),
    maps_issues        jsonb,
    -- Content, cleared after the retention window.
    domain             text,
    business_name      text,
    website            text,
    phone              text,
    address            text,
    raw                jsonb,
    content_purged_at  timestamptz
);
CREATE INDEX cards_attempt_idx ON cards (search_attempt_id);

-- One row per attempt at analysing a lead.
CREATE TABLE analyses (
    id                 uuid        PRIMARY KEY,
    run_id             uuid        NOT NULL REFERENCES runs (id),
    api_lead_id        text        NOT NULL,
    api_search_id      text,
    started_at         timestamptz NOT NULL,
    ended_at           timestamptz,
    duration_ms        integer,
    outcome            text        CHECK (outcome IN (
                           'analysed', 'failed', 'report_rejected',
                           'released_rate_limit', 'released_payment', 'released_interrupted')),
    error_type         text,
    -- Content, cleared after the retention window.
    error_message      text,
    business_name      text,
    website            text,
    result             jsonb,
    content_purged_at  timestamptz
);
CREATE INDEX analyses_run_idx     ON analyses (run_id);
CREATE INDEX analyses_lead_idx    ON analyses (api_lead_id);
CREATE INDEX analyses_search_idx  ON analyses (api_search_id);
CREATE INDEX analyses_started_idx ON analyses (started_at DESC);

-- Every OpenRouter call, with each retry it took.
CREATE TABLE llm_calls (
    id                    uuid          PRIMARY KEY,
    analysis_id           uuid          NOT NULL REFERENCES analyses (id),
    started_at            timestamptz   NOT NULL,
    model                 text          NOT NULL,
    temperature           numeric,
    max_tokens            integer,
    -- [{"status": 429, "latency_ms": 812, "retry_in_s": 2.4}, ...]
    attempts              jsonb         NOT NULL DEFAULT '[]',
    final_status          integer,
    latency_ms            integer,
    prompt_tokens         integer,
    completion_tokens     integer,
    cost_usd              numeric(12, 6),
    parsed_ok             boolean,
    -- Survives the purge: which version of the system prompt produced this pitch.
    system_prompt_sha256  text,
    -- Content, cleared after the retention window.
    system_prompt         text,
    user_prompt           text,
    response_raw          text,
    response_parsed       jsonb,
    content_purged_at     timestamptz
);
CREATE INDEX llm_calls_analysis_idx ON llm_calls (analysis_id);
CREATE INDEX llm_calls_started_idx  ON llm_calls (started_at DESC);

-- Warnings, errors and pauses.
CREATE TABLE log_entries (
    id                 uuid        PRIMARY KEY,
    run_id             uuid        NOT NULL REFERENCES runs (id),
    logged_at          timestamptz NOT NULL,
    kind               text        NOT NULL DEFAULT 'log'
                                   CHECK (kind IN ('log', 'pause_rate_limit', 'pause_payment')),
    level              text        NOT NULL,
    logger             text        NOT NULL,
    search_attempt_id  uuid        REFERENCES search_attempts (id),
    analysis_id        uuid        REFERENCES analyses (id),
    exception_type     text,
    -- Content, cleared after the retention window.
    message            text,
    exception_text     text,
    content_purged_at  timestamptz
);
CREATE INDEX log_entries_run_idx    ON log_entries (run_id);
CREATE INDEX log_entries_logged_idx ON log_entries (logged_at DESC);

-- Clears content older than the retention window; metadata and rows stay.
-- Safe to call as often as wanted: already-purged rows are skipped.
CREATE FUNCTION purge_audit_content(retention interval DEFAULT interval '90 days')
RETURNS TABLE (table_name text, rows_purged bigint)
LANGUAGE plpgsql AS $$
DECLARE
    cutoff timestamptz := now() - retention;
    n      bigint;
BEGIN
    UPDATE cards SET domain = NULL, business_name = NULL, website = NULL, phone = NULL,
                     address = NULL, raw = NULL, content_purged_at = now()
     WHERE seen_at < cutoff AND content_purged_at IS NULL;
    GET DIAGNOSTICS n = ROW_COUNT;
    table_name := 'cards'; rows_purged := n; RETURN NEXT;

    UPDATE analyses SET error_message = NULL, business_name = NULL, website = NULL,
                        result = NULL, content_purged_at = now()
     WHERE started_at < cutoff AND content_purged_at IS NULL;
    GET DIAGNOSTICS n = ROW_COUNT;
    table_name := 'analyses'; rows_purged := n; RETURN NEXT;

    UPDATE llm_calls SET system_prompt = NULL, user_prompt = NULL, response_raw = NULL,
                         response_parsed = NULL, content_purged_at = now()
     WHERE started_at < cutoff AND content_purged_at IS NULL;
    GET DIAGNOSTICS n = ROW_COUNT;
    table_name := 'llm_calls'; rows_purged := n; RETURN NEXT;

    UPDATE log_entries SET message = NULL, exception_text = NULL, content_purged_at = now()
     WHERE logged_at < cutoff AND content_purged_at IS NULL;
    GET DIAGNOSTICS n = ROW_COUNT;
    table_name := 'log_entries'; rows_purged := n; RETURN NEXT;
END;
$$;

INSERT INTO schema_migrations (version) VALUES ('001_initial');

COMMIT;